print "node dist" per line sorted by node."""

import argparse
import sys

from .graph import shortest_paths


def load_adjacency(path: str) -> dict[str, list[tuple[str, float]]]:
    adj: dict[str, list[tuple[str, float]]] = {}
    with open(path, encoding="utf-8") as f:
        for lineno, line in enumerate(f, 1):
            parts = line.split()
            if not parts:
                continue
            if len(parts) != 3:
                raise ValueError(f"{path}:{lineno}: expected 'u v weight', got {line!r}")
            u, v, w_raw = parts
            try:
                w = float(w_raw)
            except ValueError:
                raise ValueError(f"{path}:{lineno}: bad weight {w_raw!r}") from None
            adj.setdefault(u, []).append((v, w))
            adj.setdefault(v, [])
    return adj


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Dijkstra's shortest paths")
    parser.add_argument("edge_file", help="edge list file, one 'u v weight' per line")
    parser.add_argument("source", help="source node")
    args = parser.parse_args(argv)

    adj = load_adjacency(args.edge_file)
    try:
        dist = shortest_paths(adj, args.source)
    except ValueError as e:
        print(f"error: {e}", file=sys.stderr)
        return 1

    for node in sorted(dist):
        print(f"{node} {dist[node]:g}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
