from dijkstra.graph import shortest_paths


def test_greedy_trap():
    """Direct edge weight 10 must lose to the two-hop path of weight 3."""
    adj = {
        "a": [("b", 10), ("c", 1)],
        "b": [],
        "c": [("b", 2)],
        "d": [("e", 1)],
        "e": [],
        "f": [],
    }
    # Trap: greedy pick of a->b (10); correct path is a->c->b (3).
    assert shortest_paths(adj, "a") == {"a": 0.0, "c": 1.0, "b": 3.0}


def test_unreachable_nodes_absent_not_inf():
    adj = {
        "s": [("t", 5)],
        "t": [],
        "x": [("y", 1)],
        "y": [],
        "z": [],
    }
    result = shortest_paths(adj, "s")
    assert result == {"s": 0.0, "t": 5.0}
    assert "x" not in result and "y" not in result and "z" not in result
    assert not any(d == float("inf") for d in result.values())


def test_single_node_graph():
    assert shortest_paths({}, "only") == {"only": 0.0}
    assert shortest_paths({"only": []}, "only") == {"only": 0.0}


@pytest.mark.parametrize("weight", [-1.0, -0.001])
def test_negative_weight_rejected(weight):
    adj = {
        "a": [("b", 2)],
        "b": [("c", weight)],
        "c": [],
    }
    with pytest.raises(ValueError):
        shortest_paths(adj, "a")
